        "Dezelfde vorm die gebruik je in het meervoud voor alle geslachten in de nominatief en accusatief: die Kinder, die Autos, die Tische. In de datief is het der (vrouwelijk) en den (meervoud, met -n).",
        "Die kan ook een aanwijzend of betrekkelijk voornaamwoord zijn: die Frau, die dort steht (de vrouw die daar staat)."
