        "Mannelijk en onzijdig hebben ein, vrouwelijk eine. In de accusatief is het mannelijk einen: Ich habe einen Bruder. Datief: einem (mannelijk/onzijdig), einer (vrouwelijk). In het meervoud is er geen onbepaald lidwoord; bij ontkenning gebruik je kein.",
