        "Als sport gebruik je het zonder lidwoord: Ich spiele Fußball (ik speel voetbal). Voor de bal is een lidwoord nodig: der Fußball liegt im Garten.",
        "In samenstellingen: das Fußballspiel (voetbalwedstrijd), der Fußballplatz (voetbalveld)."
