        "Als bijvoeglijk naamwoord betekent gleich 'gelijk, hetzelfde': Die Kinder sind gleich alt. De uitdrukking Das ist mir gleich betekent 'dat maakt me niet uit'.",
        "Bij een plaats betekent gleich 'vlak, direct': gleich nebenan (vlak hiernaast), gleich hier (direct hier)."
