      "explanation": [
        "Kern: die Hand is een vrouwelijk zelfstandig naamwoord dat hand betekent, het deel van de arm vanaf de pols: Ich wasche mir die Hände. Het meervoud is die Hände (met umlaut).",
        "Net als in het Nederlands is Hand alleen de hand met de vingers; de hele arm vanaf de schouder is der Arm.",
        "Veelgebruikte uitdrukkingen: die Hand geben (een hand geven), in der Hand (in de hand), mit der Hand (met de hand)."
      ],
      "examples": [
        {
          "de": "Gib mir deine Hand!",
          "lv": "Geef me je hand!"
        },
        {
          "de": "Ich wasche mir die Hände.",
          "lv": "Ik was mijn handen."
        },
        {
          "de": "Er hat eine Tasche in der Hand.",
          "lv": "Hij heeft een tas in zijn hand."
        },
        {
          "de": "Sie gibt dem Chef die Hand.",
          "lv": "Zij geeft de baas een hand."
        },
        {
          "de": "Meine Hände sind kalt.",
          "lv": "Mijn handen zijn koud."
        }
      ],
      "comparison": [
        {
          "word": "der Arm",
          "meaning": "arm (vanaf de schouder)",
          "example": "Mein Arm tut weh. – Mijn arm doet pijn."
        },
        {
          "word": "der Finger",
          "meaning": "vinger",
          "example": "Ich habe einen Finger verletzt. – Ik heb een vinger bezeerd."
        },
        {
          "word": "die Faust",
          "meaning": "vuist",
          "example": "Er ballt die Faust. – Hij balt zijn vuist."
        }
      ],
      "tip": [
        "In het meervoud komt er een umlaut bij: die Hand → die Hände.",
        "Handen wassen is sich die Hände waschen: Ich wasche mir die Hände."
      ],
      "important": [
        "Verwar Hand niet met Arm: Arm is de arm van de schouder tot de pols.",
        "Het meervoud is die Hände, niet 'die Hands'."
      ],
