        "Trappen van vergelijking: leiser (zachter), am leisesten. Voor een zelfstandig naamwoord krijgt het een uitgang: eine leise Stimme, leise Musik. Vaak gebruikt als bijwoord: Die Kinder sprechen leise.",
        "Figuurlijk kan leise ook “licht, een beetje” betekenen: ein leiser Zweifel – een lichte twijfel."
