        "Meervoud: die Männer (met umlaut). Genitief: des Mannes, datief meervoud: den Männern. In samenstellingen: Ehemann, Geschäftsmann (mv. Geschäftsleute).",
        "Verschil met het woord man: man (men, je) is een voornaamwoord en schrijf je met een kleine letter en één n. De mens in het algemeen heet der Mensch."
