      "id": "a1-zum",
      "layout": "standardStudy",
      "translation": "naar de • bij de",
      "explanation": [
        "Kerngedachte: zum is een samentrekking van zu + dem, dus zu met de datief van een mannelijk of onzijdig woord. Het betekent naar of bij (richting): zum Bahnhof, zum Bäcker; ook een doel: zum Frühstück, zum Geburtstag.",
        "In het vrouwelijk is het zur (zu der), in het meervoud zu den. Met een als zelfstandig naamwoord gebruikte infinitief drukt zum een doel uit: zum Lesen (om te lezen).",
        "Zum Frühstück betekent \"bij het ontbijt\" of \"als ontbijt\", afhankelijk van de context."
      ],
      "examples": [
        {
          "de": "Ich gehe zum Bahnhof.",
          "lv": "Ik ga naar het station."
        },
        {
          "de": "Er geht zum Bäcker.",
          "lv": "Hij gaat naar de bakker."
        },
        {
          "de": "Was möchtest du zum Frühstück?",
          "lv": "Wat wil je als ontbijt?"
        },
        {
          "de": "Zum Geburtstag wünsche ich dir alles Gute.",
          "lv": "Voor je verjaardag wens ik je het allerbeste."
        },
        {
          "de": "Das Haus steht zum Verkauf.",
          "lv": "Het huis staat te koop."
        }
      ],
      "comparison": [
        {
          "word": "zur",
          "meaning": "naar / bij (vrouwelijk)",
          "example": "Ich gehe zur Schule. – Ik ga naar school."
        },
        {
          "word": "beim",
          "meaning": "bij (plaats)",
          "example": "Ich bin beim Arzt. – Ik ben bij de dokter."
        },
        {
          "word": "nach",
          "meaning": "naar (stad)",
          "example": "Ich fahre nach Berlin. – Ik ga naar Berlijn."
        }
      ],
      "tip": [
        "Zum gebruik je alleen bij der- en das-woorden: zum Mann, zum Kind; bij een vrouw: zur Frau.",
        "In de uitdrukking zum Beispiel (bijvoorbeeld) is zum een vaste vorm."
      ],
      "important": [
        "Zum = zu dem, niet zu den.",
        "Gebruik zum niet bij vrouwelijke woorden: niet \"zum Schule\", maar zur Schule."
      ],
