        "Naar de tijd vraag je met Wie viel Uhr ist es? of Wie spät ist es? Een duur in uren noem je met die Stunde: zwei Stunden.",
        "Uhr geeft een tijdstip aan (um acht Uhr), Stunde een duur (acht Stunden); het Nederlandse \"uur\" dekt beide, dus let goed op dat je ze niet verwart."
